css:
:root {
  --zt-font: "Segoe UI", Arial, sans-serif;

  --zt-metal: #D7D8DB;
  --zt-outline: #4E4E4E;
  --zt-liquid: #A0CFE9;

  --zt-valve: #0E0E55;
  --zt-steam: #930606;
  --zt-control: #01524F;
  --zt-text: #000000;

  --zt-process-width: 1.6px;
  --zt-outline-width: 1.8px;
  --zt-valve-width: 1.4px;
}

/* Entorno transparente */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.zt-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--zt-font);
  pointer-events: none;
}

.zt-svg {
  display: block;
  width: 100%;
  height: 100%;
  background: transparent;
  shape-rendering: geometricPrecision;
}

.zt-widget,
.zt-widget * {
  animation: none !important;
  transition: none !important;
}

/* Acabado metálico */

.zt-metal-stop {
  stop-color: var(--zt-metal);
}

.zt-liquid-stop {
  stop-color: var(--zt-liquid);
}

.zt-metal {
  fill: url("#zt-metal-gradient");
  stroke: var(--zt-outline);
  stroke-width: 1.4px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.zt-equipment-shadow {
  filter: url("#zt-equipment-shadow");
}

.zt-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.48;
}

/* Tanques */

.zt-tank-shell {
  fill: url("#zt-metal-gradient");
  stroke: var(--zt-outline);
  stroke-width: var(--zt-outline-width);
  stroke-linejoin: round;
}

.zt-tank-liquid {
  fill: url("#zt-liquid-gradient");
  stroke: none;
}

.zt-tank-texture {
  fill: url("#zt-liquid-pattern");
  stroke: none;
  opacity: 0.16;
}

.zt-wave {
  fill: none;
  stroke: #527F99;
  stroke-width: 0.65px;
  stroke-linecap: round;
}

/* Tuberías */

.zt-pipe {
  fill: none;
  stroke: var(--zt-outline);
  stroke-width: var(--zt-process-width);
  stroke-linecap: butt;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.zt-pipe-secondary {
  stroke-width: 1.2px;
}

.zt-flow-arrow {
  fill: var(--zt-outline);
  stroke: none;
}

/* Válvulas transparentes */

.zt-valve-body {
  fill: none;
  stroke: var(--zt-valve);
  stroke-width: var(--zt-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.zt-valve-link {
  fill: none;
  stroke: var(--zt-valve);
  stroke-width: 0.7px;
  stroke-linecap: round;
}

.zt-valve-actuator {
  fill: var(--zt-valve);
  stroke: var(--zt-valve);
  stroke-width: 1px;
}

/* Bombas */

.zt-pump-body {
  fill: url("#zt-metal-gradient");
  stroke: var(--zt-outline);
  stroke-width: 1.5px;
  stroke-linejoin: round;
}

.zt-pump-detail {
  fill: none;
  stroke: var(--zt-outline);
  stroke-width: 1.2px;
  stroke-linecap: round;
}

.zt-pump-red {
  stroke: var(--zt-steam);
}

.zt-pump-blue {
  stroke: var(--zt-valve);
}

/* Símbolos circulares de las tuberías */

.zt-inline-body {
  fill: url("#zt-metal-gradient");
  stroke: var(--zt-outline);
  stroke-width: 1.2px;
}

.zt-inline-sector {
  fill: var(--zt-outline);
  stroke: none;
}

/* Elementos mecánicos */

.zt-mechanical {
  fill: none;
  stroke: var(--zt-outline);
  stroke-width: 1.3px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.zt-mechanical-fine {
  fill: none;
  stroke: var(--zt-outline);
  stroke-width: 0.85px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Placas y textos */

.zt-label-plate {
  fill: url("#zt-metal-gradient");
  stroke: var(--zt-outline);
  stroke-width: 1.4px;
}

.zt-label {
  fill: var(--zt-text);
  font-family: var(--zt-font);
  font-size: 12.5px;
  font-weight: 600;
}

.zt-equipment-label {
  fill: var(--zt-text);
  font-family: var(--zt-font);
  font-size: 13px;
  font-weight: 600;
}

.zt-footer {
  fill: var(--zt-text);
  font-family: var(--zt-font);
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}
